/// <summary>
/// Extends SysOperationServiceController
/// </summary>
class AVACreditLimitGroupAssignmentController extends SysOperationServiceController
{
}

Method.Source:
/// <summary>
/// new method
/// </summary>
protected void new()
{
    super(classStr(AVACreditLimitGroupAssignmentService), methodStr(AVACreditLimitGroupAssignmentService, process), SysOperationExecutionMode::Synchronous);
}

/// <summary>
/// default class description
/// </summary>
/// <returns>ClassDescription</returns>
public ClassDescription defaultCaption()
{
    return "@NDX:NXACRLGroupAssignment";
}

/// <summary>
/// construct method of class
/// </summary>
/// <param name = "_executionMode">SysOperationExecutionMode, default SysOperationExecutionMode::Synchronous</param>
/// <returns>AVACreditLimitGroupAssignmentController</returns>
public static AVACreditLimitGroupAssignmentController construct(SysOperationExecutionMode _executionMode = SysOperationExecutionMode::Synchronous)
{
    AVACreditLimitGroupAssignmentController controller;
    controller = new AVACreditLimitGroupAssignmentController();
    controller.parmExecutionMode(_executionMode);
    return controller;
}

/// <summary>
/// main method
/// </summary>
/// <param name = "_args">Args</param>
public static void main(Args _args)
{
    CustTable   custTable = _args.record();
    AVACreditLimitGroupAssignmentController controller;
    AVACreditLimitGroupAssignmentContract   contract;
    controller = AVACreditLimitGroupAssignmentController::construct();
    contract = controller.getDataContractObject();
    contract.parmCustAccount(custTable.AccountNum);
    contract.parmDataAreaId(custTable.DataAreaId);
    controller.parmArgs(_args);
    controller.startOperation();
}
